import Image from "next/image";
import { cn } from "@/lib/utils";

/**
 * A real screenshot of the app, generated by scripts/screenshots.ts from the
 * demo workspace. Framed as a sheet: a rule and a hard shadow, no browser chrome.
 */
export function Screenshot({ name, alt, caption, className, priority }: { name: string; alt: string; caption?: string; className?: string; priority?: boolean }) {
  return (
    <figure className={cn("min-w-0", className)}>
      <div className="sheet-raised overflow-hidden">
        <Image src={`/screens/${name}.webp`} alt={alt} width={1440} height={900} sizes="(min-width: 1024px) 60vw, 100vw" priority={priority} className="block h-auto w-full" />
      </div>
      {caption ? <figcaption className="mt-3 text-sm text-ink-muted">{caption}</figcaption> : null}
    </figure>
  );
}
